// Scenes. The background art and the walls, lights and regions are generated by dev/maps/*.py (the project's battlemap renderer);
// this reads their data (dev/maps/out/*.json) and builds the Scene documents. Foundry v14 keeps the background on a Level.
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { stableId, MODULE_ID, ASSETS } from "./common.mjs";
import { F } from "./folders.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const data = name => JSON.parse(readFileSync(resolve(here, "../dev/maps/out", `${name}.json`), "utf8"));

const WALL = {
  solid: { move: 20, sight: 20, light: 20, sound: 20, door: 0, ds: 0 },
  door: { move: 20, sight: 20, light: 20, sound: 20, door: 1, ds: 0 },
  locked: { move: 20, sight: 20, light: 20, sound: 20, door: 1, ds: 2 },
  glass: { move: 20, sight: 0, light: 0, sound: 10, door: 0, ds: 0 },
  glassdoor: { move: 20, sight: 0, light: 0, sound: 10, door: 1, ds: 2 }
};
const REGION_COLORS = ["#c0392b", "#2e86c1", "#28b463", "#d4ac0d", "#8e44ad", "#ca6f1e", "#17a589", "#7f8c8d"];

function scene(key, name, file, { grid, journal = null, darkness = 0, globalLight = true, tokenVision = false, sort = 0, flags = {}, navName = null }) {
  const d = data(file);
  const [gw, gh, G] = d.grid;
  const width = gw * G, height = gh * G;
  const levelId = stableId(`level:${key}`);
  return {
    _id: stableId(`scene:${key}`), name, navName: navName ?? name, navigation: false, folder: F.scenes._id, sort,
    width, height, padding: 0,   // walls, lights, regions and drawings use image coordinates, so no padding offset backgroundColor: "#1a1612", thumb: `${ASSETS}/scenes/${file}-thumb.webp`,
    initial: { x: width / 2, y: height / 2, scale: null },
    grid: { type: 1, size: grid.size ?? G, distance: grid.distance ?? 5, units: grid.units ?? "ft", color: "#000000", alpha: grid.alpha ?? 0.15 },
    levels: [{ _id: levelId, name: "Ground", sort: 0, background: { src: `${ASSETS}/scenes/${file}.webp` } }],
    initialLevel: levelId,
    tokenVision, environment: { darknessLevel: darkness, globalLight: { enabled: globalLight } },
    journal, ownership: { default: 0 },
    walls: d.walls.map((w, i) => ({ _id: stableId(`wall:${key}:${i}`), c: w.c, ...(WALL[w.kind] ?? WALL.solid), dir: 0, flags: {} })),
    lights: d.lights.map((l, i) => ({
      _id: stableId(`light:${key}:${i}`), x: Math.round(l.x), y: Math.round(l.y), rotation: 0, walls: true, vision: false, hidden: !!l.hidden,
      config: { bright: l.bright, dim: l.dim, color: l.color, alpha: l.alpha, angle: 360, luminosity: 0.5,
        animation: { type: l.anim ?? null, speed: l.speed ?? 3, intensity: l.intensity ?? 3 } },
      flags: { [MODULE_ID]: { name: l.name, state: l.state ?? null } }
    })),
    regions: d.regions.map((r, i) => ({ _id: stableId(`region:${key}:${i}`), name: r.name, color: REGION_COLORS[i % REGION_COLORS.length],
      shapes: r.shapes, behaviors: [], flags: { [MODULE_ID]: { kind: r.kind } } })),
    drawings: [], notes: [], tokens: [], tiles: [], sounds: [],
    flags: { [MODULE_ID]: flags }
  };
}

const J = key => stableId(`journal:${key}`);
export const SCENES = [
  scene("round1", "Round 1: The Projectile Shoot", "round1-field", { grid: { size: 100 }, journal: J("round1"), sort: 100 }),
  scene("round2", "Round 2: The Protection Run", "round2-track", { grid: { size: 100 }, journal: J("round2"), sort: 200 }),
  scene("conservatory", "Round 3: The Clockwork Conservatory", "conservatory", { grid: { size: 100 }, journal: J("round3"), sort: 300,
    darkness: 0.9, globalLight: false, tokenVision: true, flags: { conservatory: true } }),
  scene("edretnor", "The Crawl: Edretnor", "edretnor", { grid: { size: 300, distance: 1, units: "tile", alpha: 0.35 }, journal: J("crawl"), sort: 400,
    flags: { crawl: true } })
];
